using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using System.Runtime.Serialization;
[DataContract] sealed class MillPoolState{[DataMember]public float X,Y,Z;[DataMember]public double Remaining;}
public partial class MigrationScene {
 sealed class MillPool{public Vector3 Position;public double Remaining;public Node3D Node;}
 readonly List<MillPool> millPools=new();double millPoolTick;Node3D millWarning;string millWarningKey="";ProgressBar millHealth;Label millLabel;
 MeshInstance3D MillRing(Node3D root,float radius,Color color){var mesh=new SurfaceTool();mesh.Begin(Mesh.PrimitiveType.Triangles);for(int i=0;i<80;i++){float a=i*Mathf.Tau/80,b=(i+1)*Mathf.Tau/80;Vector3 A(float angle,float r)=>new(Mathf.Sin(angle)*r,.05f,Mathf.Cos(angle)*r);foreach(var v in new[]{A(a,radius),A(b,radius-.22f),A(b,radius),A(a,radius),A(a,radius-.22f),A(b,radius-.22f)})mesh.AddVertex(v);}var material=new StandardMaterial3D{AlbedoColor=color,Transparency=BaseMaterial3D.TransparencyEnum.Alpha,ShadingMode=BaseMaterial3D.ShadingModeEnum.Unshaded,CullMode=BaseMaterial3D.CullModeEnum.Disabled,EmissionEnabled=true,Emission=color};var item=new MeshInstance3D{Mesh=mesh.Commit(),MaterialOverride=material,CastShadow=GeometryInstance3D.ShadowCastingSetting.Off};root.AddChild(item);return item;}
 void CreateMillPool(Vector3 position,double remaining=9){if(millPools.Count>=9){millPools[0].Node.QueueFree();millPools.RemoveAt(0);}var n=new Node3D{Position=position};AddChild(n);MillRing(n,3,new(.38f,.90f,.12f,.85f));var puddle=Ellipsoid(n,new(0,.04f,0),new(2.85f,.035f,2.85f),new(.23f,.42f,.055f));puddle.MaterialOverride=new StandardMaterial3D{AlbedoColor=new(.23f,.48f,.055f,.65f),Transparency=BaseMaterial3D.TransparencyEnum.Alpha,EmissionEnabled=true,Emission=new(.10f,.23f,.02f)};millPools.Add(new(){Position=position,Remaining=remaining,Node=n});}
 void CreateMillVomit(Infected boss){var direction=boss.BossAim-boss.Body.Position;direction.Y=0;direction=direction.LengthSquared()>.01?direction.Normalized():Vector3.Forward;foreach(float distance in new[]{5f,9f,13f}){var p=boss.Body.Position+direction*distance;p.Y=(float)millFloor;CreateMillPool(p);}ImpactParticles(boss.Body.Position+Vector3.Up*3.6f,new(.28f,.70f,.09f),24,.12f);}
 void ClearMillPools(){foreach(var p in millPools)p.Node.QueueFree();millPools.Clear();if(GodotObject.IsInstanceValid(millWarning))millWarning.QueueFree();millWarning=null;millWarningKey="";}
 void TickMillPools(double dt){if(CoopClient)return;for(int i=millPools.Count-1;i>=0;i--){millPools[i].Remaining-=dt;if(millPools[i].Remaining<=0){millPools[i].Node.QueueFree();millPools.RemoveAt(i);}}millPoolTick-=dt;if(millPoolTick>0)return;millPoolTick=1;foreach(var player in MillPlayers())if(millPools.Any(p=>Distance(p.Position,player.Body.Position)<3))MillDamage(player.Game,player.Body,5,false);if(Dog.Rescued&&!Dog.Dead&&DogPresent&&millPools.Any(p=>Distance(p.Position,DogPoint)<3))HurtRescueDog(5);foreach(var n in Community.Survivors)if(millPools.Any(p=>Distance(p.Position,NpcPoint(n))<3))HurtCommunity(n,5);}
 void ApplyMillPools(List<MillPoolState> incoming){if(incoming==null)incoming=new();bool changed=incoming.Count!=millPools.Count||incoming.Where((p,i)=>i<millPools.Count&&millPools[i].Position.DistanceTo(new(p.X,p.Y,p.Z))>.1f).Any();if(changed){ClearMillPools();foreach(var p in incoming)CreateMillPool(new(p.X,p.Y,p.Z),p.Remaining);}else for(int i=0;i<incoming.Count;i++)millPools[i].Remaining=incoming[i].Remaining;}
 void DrawMillEncounter(){if(millHealth==null){millHealth=new ProgressBar{Position=new(380,188),Size=new(520,12),ShowPercentage=false,MaxValue=1};hudRoot.AddChild(millHealth);millLabel=HudLabel(16);}var boss=infected.FirstOrDefault(e=>IsMillBoss(e.Id)&&Distance(e.Body.Position,player.Position)<80);millHealth.Visible=boss!=null;millLabel.Visible=boss!=null;if(boss==null){if(GodotObject.IsInstanceValid(millWarning))millWarning.Visible=false;return;}millHealth.Value=boss.Hp/Math.Max(1,boss.MaxHp);millLabel.Position=new(380,160);string attack=boss.BossState switch{"slam"=>"GROUND SLAM / leave the orange circle!","retch"=>"CORROSIVE VOMIT / sidestep, avoid green sludge!","charge-windup"=>"CHARGE / bait into logs, then sidestep!","charge"=>"CHARGING!","stunned"=>"STUNNED / DOUBLE DAMAGE!",_ when boss.BossState.StartsWith("recover")=>"EXPOSED / attack now!",_=>boss.Hp<boss.MaxHp*.5?"ENRAGED / shorter warnings":"Keep moving / watch his wind-ups"};millLabel.Text=$"THE FOREMAN   {(int)boss.Hp}/{(int)boss.MaxHp}\n{attack}";
  string key=boss.Id+"/"+boss.BossState+"/"+boss.BossStep;if(key!=millWarningKey){if(GodotObject.IsInstanceValid(millWarning))millWarning.QueueFree();millWarning=new Node3D();AddChild(millWarning);millWarningKey=key;if(boss.BossState=="slam")MillRing(millWarning,6.5f,new(.98f,.42f,.06f,.9f));else if(boss.BossState is "retch" or "charge-windup" or "charge"){float length=boss.BossState=="retch"?16:22;var delta=boss.BossAim-boss.Body.Position;delta.Y=0;var direction=delta.LengthSquared()>.01?delta.Normalized():Vector3.Forward;var lane=new MeshInstance3D{Mesh=new BoxMesh{Size=new(boss.BossState=="retch"?5:3,.04f,length)},Position=direction*length/2+Vector3.Up*.07f,MaterialOverride=new StandardMaterial3D{AlbedoColor=boss.BossState=="retch"?new(.35f,.9f,.08f,.38f):new Color(.95f,.12f,.04f,.4f),Transparency=BaseMaterial3D.TransparencyEnum.Alpha,ShadingMode=BaseMaterial3D.ShadingModeEnum.Unshaded}};lane.Rotation=new(0,Mathf.Atan2(-direction.X,-direction.Z),0);millWarning.AddChild(lane);}else if(boss.BossState=="stunned"||boss.BossState.StartsWith("recover"))MillRing(millWarning,1.8f,new(.22f,.82f,.96f,.8f));}millWarning.Visible=true;millWarning.Position=boss.Body.Position;
  if(boss.Visual.HasNode("Torso")){var torso=boss.Visual.GetNode<Node3D>("Torso");foreach(string side in new[]{"Left","Right"}){var arm=boss.Visual.GetNode<Node3D>(side+"Arm");arm.RotationDegrees=new(boss.BossState=="slam"?-145:boss.BossState=="retch"?-45:boss.BossState is "charge" or "charge-windup"?-65:boss.BossState=="stunned"?20:-15,0,side=="Left"?-12:12);}torso.RotationDegrees=new(boss.BossState=="slam"?-25:boss.BossState=="retch"?25:boss.BossState=="stunned"?35:0,0,Mathf.Sin((float)game.Clock*2)*3);}
 }
